251	    @Override
252	    @Transactional
253	    public void saveOwner(Owner owner) throws DataAccessException {
254	        boolean isNew = owner.isNew();
255	        // Resolve the effective registration date (supplied, or defaulted to the server date) and
256	        // roll it forward to the next business day so it never lands on a weekend. Everything
257	        // derived from the registration date below must use this adjusted value.
258	        LocalDate registrationDate = toBusinessDay(
259	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
260	        owner.setRegistrationDate(registrationDate);
261	        if (owner.isNew()) {
262	            // Resolve the household first so the owner's householdId is part of its identityKey. The
263	            // members are existing owners with the same last name and address; joining them makes this
264	            // owner share their stable householdId (back-filled onto any member still missing it).
265	            List<Owner> householdMembers = findHouseholdMembers(owner);
266	            if (!householdMembers.isEmpty()) {
267	                owner.setHouseholdId(resolveHouseholdId(householdMembers));
268	            }
269	            // Size of the household after this create: the existing members plus this new owner.
270	            owner.setHouseholdMemberCount(householdMembers.size() + 1);
271	        }
272	        // Single consolidated duplicate check: reject only when the new owner's WHOLE identityKey
273	        // (normalizedTelephone | email-or-empty | householdId) equals an existing owner's. This
274	        // subsumes the former separate telephone, email and household checks.
275	        if (owner.isNew() && isIdentityKeyAlreadyUsed(owner)) {
276	            throw new DuplicateIdentityException(owner.getIdentityKey());
277	        }
278	        if (owner.isNew()
279	            && countOwnersInCity(owner) >= CityOwnerLimitExceededException.MAX_OWNERS_PER_CITY) {
280	            throw new CityOwnerLimitExceededException(owner.getCity());
281	        }
282	        if (owner.isNew()
283	            && countOwnersRegisteredOn(registrationDate) >= DailyOwnerLimitExceededException.MAX_OWNERS_PER_DAY) {
284	            throw new DailyOwnerLimitExceededException(registrationDate);
285	        }
286	        if (owner.isNew() && owner.getCustomerCode() == null) {
287	            owner.setCustomerCode(generateCustomerCode(owner));
288	        }
289	        if (owner.isNew()) {
290	            owner.setNamesakeCount(countNamesakes(owner));
291	            owner.setBulkSignupWarning(
292	                countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
293	        }
294	        if (owner.getMembershipNumber() == null) {
295	            owner.setMembershipNumber(generateMembershipNumber(owner));
296	        }
297	        ownerRepository.save(owner);
298	        if (isNew) {
299	            AUDIT.info("owner created id={} customerCode={} membershipLevel={} registrationDate={}",
300	                owner.getId(), owner.getCustomerCode(), owner.getMembershipLevel(),
301	                owner.getRegistrationDate());
302	        }
303	    }
304	
305	    /**
306	     * Report whether {@code owner}'s derived {@code identityKey} is already used by any existing
307	     * owner. The key consolidates telephone, email and household into one value, so two owners
308	     * collide only when their whole key is equal (see {@link Owner#getIdentityKey()}). By this point
309	     * the owner's {@code householdId} has been resolved, so its key is complete.
310	     */
311	    private boolean isIdentityKeyAlreadyUsed(Owner owner) {
312	        String identityKey = owner.getIdentityKey();
313	        return ownerRepository.findAll().stream()
314	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
315	    }
316	
317	    /**
318	     * Count the owners that already exist (before this create) sharing the same first name and last
319	     * name as {@code owner}, compared case-insensitively. Returns zero when the owner's name is
320	     * unique among the existing owners.
321	     */
322	    private int countNamesakes(Owner owner) {
323	        String firstName = owner.getFirstName();
324	        String lastName = owner.getLastName();
325	        if (firstName == null || lastName == null) {
326	            return 0;
327	        }
328	        return (int) ownerRepository.findAll().stream()
329	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
330	                && lastName.equalsIgnoreCase(existing.getLastName()))
331	            .count();
332	    }
333	
334	    /**
335	     * Find the owners that already belong to the same household as {@code owner}, i.e. have the same
336	     * last name and the same address. Last names are compared case-insensitively with collapsed
337	     * whitespace; addresses are compared in their canonical normalized form (see
338	     * {@link AddressNormalizer}), so differences in letter case, runs of spaces or street-type
339	     * abbreviations are ignored. Returns an empty list when the owner has no last name or address to
340	     * match on.
341	     */
342	    private List<Owner> findHouseholdMembers(Owner owner) {
343	        String lastName = normalizeHouseholdKey(owner.getLastName());
344	        String address = AddressNormalizer.normalize(owner.getAddress());
345	        if (lastName == null || address == null) {
346	            return List.of();
347	        }
348	        return ownerRepository.findAll().stream()
349	            .filter(existing -> lastName.equals(normalizeHouseholdKey(existing.getLastName()))
350	                && address.equals(AddressNormalizer.normalize(existing.getAddress())))
351	            .toList();
352	    }
353	
354	    /**
355	     * Resolve the stable {@code householdId} shared by a household. If any existing member already
356	     * carries one it is reused so the identifier stays stable as further owners join; otherwise a
357	     * new one is generated. The resolved value is back-filled onto every member that is missing it
358	     * (or has a different one) so all members of the household share the same identifier.
359	     */
360	    private String resolveHouseholdId(List<Owner> members) {
361	        String householdId = members.stream()
362	            .map(Owner::getHouseholdId)
363	            .filter(id -> id != null && !id.isBlank())
364	            .findFirst()
365	            .orElseGet(() -> UUID.randomUUID().toString());
366	        for (Owner member : members) {
367	            if (!householdId.equals(member.getHouseholdId())) {
368	                member.setHouseholdId(householdId);
369	                ownerRepository.save(member);
370	            }
371	        }
372	        return householdId;
373	    }
374	
375	    /**
376	     * Normalize a value for case-insensitive, whitespace-insensitive household comparison by
377	     * trimming, collapsing internal runs of whitespace to a single space and lower-casing it.
378	     */
379	    private String normalizeHouseholdKey(String value) {
380	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase();
381	    }
382	
383	    /**
384	     * Build an owner's {@code customerCode} as {@code '<REGION>-<HASH8>'}: REGION is the region
385	     * code resolved from the owner's postcode (falling back to the owner's city, else
386	     * {@code 'UNKNOWN'}), and HASH8 the first 8 upper-case hex characters of SHA-256 computed over
387	     * the owner's normalized telephone concatenated with the owner's last name (e.g.
388	     * {@code 'NSW-1A2B3C4D'}). There are no per-city sequence numbers; the identity is fully
389	     * derived from the owner's own attributes.
390	     */
391	    private String generateCustomerCode(Owner owner) {
392	        return PostcodeRules.resolveRegion(owner.getPostcode(), owner.getCity()) + "-" + customerHash(owner);
393	    }
394	
395	    /**
396	     * Compute the hash segment of an owner's {@code customerCode}: the first 8 upper-case hex
397	     * characters of SHA-256 over the UTF-8 bytes of the owner's normalized telephone concatenated
398	     * with the owner's last name.
399	     */
400	    private String customerHash(Owner owner) {
401	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
402	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
403	        byte[] digest;
404	        try {
405	            digest = MessageDigest.getInstance("SHA-256")
406	                .digest((telephone + lastName).getBytes(StandardCharsets.UTF_8));
407	        } catch (NoSuchAlgorithmException e) {
408	            throw new IllegalStateException("SHA-256 is required but not available", e);
409	        }
410	        StringBuilder hex = new StringBuilder(16);
411	        for (int i = 0; i < 4; i++) {
412	            hex.append(String.format("%02X", digest[i]));
413	        }
414	        return hex.toString();
415	    }
416	
417	    /**
418	     * Count the owners that already exist (before this create) in the same city as {@code owner},
419	     * compared case-insensitively.
420	     */
421	    private long countOwnersInCity(Owner owner) {
422	        String city = owner.getCity();
423	        return ownerRepository.findAll().stream()
424	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
425	            .count();
426	    }
427	
428	    /**
429	     * Count the owners that already exist (before this create) whose {@code registrationDate} falls
430	     * on the given {@code date}. Used to enforce the per-day create cap.
431	     */
432	    private long countOwnersRegisteredOn(LocalDate date) {
433	        return ownerRepository.findAll().stream()
434	            .filter(existing -> date.equals(existing.getRegistrationDate()))
435	            .count();
436	    }
437	
438	    /**
439	     * Roll {@code date} forward to the next business day when it falls on a weekend: a Saturday or
440	     * Sunday becomes the following Monday, while a weekday is returned unchanged. Registration dates
441	     * are required to fall on a business day.
442	     */
443	    private LocalDate toBusinessDay(LocalDate date) {
444	        switch (date.getDayOfWeek()) {
445	            case SATURDAY:
446	                return date.plusDays(2);
447	            case SUNDAY:
448	                return date.plusDays(1);
449	            default:
450	                return date;
451	        }
452	    }
453	
454	    /**
455	     * Build an owner's {@code membershipNumber} as {@code '<customerCode>-M<YY>'}, where YY is the
456	     * last two digits of the owner's {@code registrationDate} year (e.g. {@code 'NSW-1A2B3C4D-M26'}).
457	     */
458	    private String generateMembershipNumber(Owner owner) {
459	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
460	        return String.format("%s-M%s", owner.getCustomerCode(), yy);
461	    }
462	
463	    @Override
464	    @Transactional(readOnly = true)
465	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
466	        return ownerRepository.findByLastName(lastName);
467	    }
468	
469	    @Override
470	    @Transactional(readOnly = true)
471	    public Collection<Visit> findVisitsByPetId(int petId) {
472	        return visitRepository.findByPetId(petId);
473	    }
474	
475	    @Override
476	    @Transactional(readOnly = true)
477	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
478	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
479	    }
480	
481	    private <T> T findEntityById(Supplier<T> supplier) {
482	        try {
483	            return supplier.get();
484	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
485	            // Just ignore not found exceptions for Jdbc/Jpa realization
486	            return null;
487	        }
488	    }
489	
490	}
